        case dialogKind = "dialogKind"
        case payload = "payload"
        case toolUseId = "toolUseId"
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.threadId = try c.decode(String.self, forKey: .threadId)
        self.requestId = try c.decode(String.self, forKey: .requestId)
        self.dialogKind = try c.decode(String.self, forKey: .dialogKind)
        self.payload = try c.decode(JSONValue.self, forKey: .payload)
        self.toolUseId = try c.decodeIfPresent(String.self, forKey: .toolUseId)
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(threadId, forKey: .threadId)
        try c.encode(requestId, forKey: .requestId)
        try c.encode(dialogKind, forKey: .dialogKind)
        try c.encode(payload, forKey: .payload)
        try c.encodeIfPresent(toolUseId, forKey: .toolUseId)
    }
}

public enum DialogRequestResponse: Codable, Sendable, Hashable {
    case completed(Completed)
    case cancelled(Cancelled)
    /// A variant this client does not know yet (newer server).
    case unknown(JSONValue)

    public var behavior: String {
        switch self {
        case .completed: return "completed"
        case .cancelled: return "cancelled"
        case .unknown(let v): return v["behavior"]?.stringValue ?? ""
        }
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: AnyKey.self)
        let tag = try c.decodeIfPresent(String.self, forKey: AnyKey("behavior"))
        switch tag {
        case "completed": self = .completed(try Completed(from: decoder))
        case "cancelled": self = .cancelled(try Cancelled(from: decoder))
        default: self = .unknown(try JSONValue(from: decoder))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .completed(let v): try v.encode(to: encoder)
        case .cancelled(let v): try v.encode(to: encoder)
        case .unknown(let v): try v.encode(to: encoder)
        }
    }

    public struct Completed: Codable, Sendable, Hashable {
        public var behavior: String = "completed"
        public var result: JSONValue

        public init(result: JSONValue) {
            self.result = result
        }

        private enum CodingKeys: String, CodingKey {
            case behavior = "behavior"
            case result = "result"
        }

        public init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            self.behavior = try c.decode(String.self, forKey: .behavior)
            self.result = try c.decode(JSONValue.self, forKey: .result)
        }

        public func encode(to encoder: any Encoder) throws {
            var c = encoder.container(keyedBy: CodingKeys.self)
            try c.encode(behavior, forKey: .behavior)
            try c.encode(result, forKey: .result)
        }
    }

    public struct Cancelled: Codable, Sendable, Hashable {
        public var behavior: String = "cancelled"

        public init() {
        }

        private enum CodingKeys: String, CodingKey {
            case behavior = "behavior"
        }

        public init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            self.behavior = try c.decode(String.self, forKey: .behavior)
        }

        public func encode(to encoder: any Encoder) throws {
            var c = encoder.container(keyedBy: CodingKeys.self)
            try c.encode(behavior, forKey: .behavior)
        }
    }
}

/// Server → client requests that the client must answer.
public enum ServerRequest: Sendable, Hashable {
    case permissionRequest(PermissionRequestParams)
    case questionRequest(QuestionRequestParams)
    case planApprove(PlanApproveParams)
    case elicitationRequest(ElicitationRequestParams)
    case dialogRequest(DialogRequestParams)
    case unknown(method: String, params: JSONValue)

    public init(method: String, params: Data, decoder: JSONDecoder = JSONDecoder()) throws {
        switch method {
        case "permission/request": self = .permissionRequest(try decoder.decode(PermissionRequestParams.self, from: params))
        case "question/request": self = .questionRequest(try decoder.decode(QuestionRequestParams.self, from: params))
        case "plan/approve": self = .planApprove(try decoder.decode(PlanApproveParams.self, from: params))
        case "elicitation/request": self = .elicitationRequest(try decoder.decode(ElicitationRequestParams.self, from: params))
        case "dialog/request": self = .dialogRequest(try decoder.decode(DialogRequestParams.self, from: params))
        default: self = .unknown(method: method, params: try decoder.decode(JSONValue.self, from: params))
        }
    }

    public var requestId: String? {
        switch self {
        case .permissionRequest(let p): return p.requestId
        case .questionRequest(let p): return p.requestId
        case .planApprove(let p): return p.requestId
        case .elicitationRequest(let p): return p.requestId
        case .dialogRequest(let p): return p.requestId
        case .unknown(_, let p): return p["requestId"]?.stringValue
        }
    }
    public var threadId: String? {
        switch self {
        case .permissionRequest(let p): return p.threadId
        case .questionRequest(let p): return p.threadId
        case .planApprove(let p): return p.threadId
        case .elicitationRequest(let p): return p.threadId
        case .dialogRequest(let p): return p.threadId
        case .unknown(_, let p): return p["threadId"]?.stringValue
        }
    }
}
